// D11 人才Tab·推荐 + D11·D 搜人才 —— 企业端与求职端同构：本屏镜像求职端「看市场」（A14）。
//
// 与「在谈」共用顶栏（在招岗位左右平铺切换 + 在谈/推荐子视图），两屏切换时顶部不动、
// 只有列表在换 —— 与求职端 A6/A14 的同构硬要求一致；顶栏版式镜像求职端「顶部意向栏」。
//
// 卡片结构（镜像市场卡；2026-09-08 产品负责人定稿「去名改版」）：
//          头行（性别裸符号 + 年限｜学历｜求职状态 + 右侧匹配环）→ 信息行 ×2 → 亮点标签行
//          → 分隔线 → 底行「★ 收藏 / 让AI代理去聊」。左滑露出「不合适」。
// 2026-09-10 起卡面只剩一份：Mock / Backend 都调 组件/列表卡片/招聘推荐卡（字段由
// 数据/列表卡片映射 投影），本屏只留连接层 —— 列表、scope、操作锁与回调。
// 双盲语义：卡上无名字、无代号、无头像（名字/代号对招聘方决策价值为零），绝不出现真名；
// 不谈薪 —— 「薪资带有交集」结论也不再上卡。代号只在匿名在线简历页 / 不合适原因层出现。
//
// P4 模式边界：Backend 列表只来自当前岗位（水合后的 job_id 载体）的招聘可用候选快照，
// 经 从P4招聘候选 投影；不读 推荐列表/收藏候选/不合适候选/已接触推荐/匿名简历表/薪资初筛。
// 反馈（收藏/淘汰）服务端先行、失败绝不移动卡片；委托无确认层、原地停留，进行中回执
// 交给 use发现推荐委托轮询 按节拍刷新，暂停表把状态文案覆盖成中性文案；六个闭合委托
// 状态的卡片文案与「查看进展」导航统一走 映射P4委托展示 的投影。
// 第二批（2026-09-09 产品负责人「把这个筛选的功能都删了」）：顶栏「筛选 ▾」与 候选筛选抽屉
// （规则清单 + 「只看收藏」本地开关）整体删除；规则的 canonical 入口只剩 企业代理设置。
// Mock 保持原型行为原样：一键派发 接触推荐候选、补给推荐、零 P4 请求。

import { useEffect, useMemo, useRef, useState } from 'react';
import 样式 from './候选推荐.module.css';
import 下拉刷新 from '../组件/下拉刷新';
import { 主页外壳, 滚动区, 代理横幅 } from '../组件/通用';
import { 轻提示 } from '../组件/轻提示';
import { BFF错误 } from '../数据/HTTP客户端';
import { use应用状态 } from '../状态/应用状态';
import 滑动行 from '../组件/滑动行';
import { use导航 } from '../路由/导航钩子';
import 弹层框架 from '../组件/弹层框架';
import { 路径 } from '../路由/路径表';
import 招聘推荐卡 from '../组件/列表卡片/招聘推荐卡';
import { 从Mock推荐到卡信息, 从招聘摘要到卡信息 } from '../数据/列表卡片映射';
// 求职状态文案的表已挪到数据层（列表卡片映射 要用）；这里同名转出，匿名在线简历等
// 既有消费者不受影响。
export { 求职状态文案 } from '../数据/列表卡片映射';
import type { 推荐候选 } from '../数据/类型';
import {
  从P4招聘候选, P4已开案, P4淘汰原因码, 判断P4招聘组织前提, 映射P4委托展示,
} from '../数据/发现推荐映射';
import type { P4招聘候选页面 } from '../数据/招聘数据源类型';
import { P4错误文案, P4范围键 } from '../状态/后端/发现推荐操作';
import { P4委托进度未知文案, use发现推荐委托轮询 } from '../状态/后端/use发现推荐委托轮询';

/** 与 企业在谈候选 同款截短：顶栏只取「 · 」前的主名，两屏切换顶栏不跳变 */
function 岗位名截短(名称: string): string {
  return 名称.split(' · ')[0];
}

/** 「不合适」的四个原因。这是给代理的负反馈样本，所以要具体到可训练，而不是一个笼统的 ✕ */
const 不合适原因表 = ['年限不足', '方向不符', '主栈不符', '其他'];

/** 招聘端委托的业务 pair 键：岗位 + 推荐（本次周期集合与按卡忙态共用同一把键）。 */
const 委托键 = (jobId: string, recommendationId: string) => `${jobId}|${recommendationId}`;

export default function 候选推荐() {
  const { 数据源模式 } = use应用状态();
  return 数据源模式 === 'backend' ? <Backend候选推荐 /> : <Mock候选推荐 />;
}

/** Mock 原型分支：静态推荐表 + 全局归约，行为与接线前逐字一致。 */
function Mock候选推荐() {
  const { 状态, 派发 } = use应用状态();
  const { 跳转 } = use导航();
  // 同一时刻只允许一张卡滑开，存的是那张卡的候选编号
  const [滑开的, 设滑开的] = useState<string | null>(null);
  // 待选原因的候选；非 null 时弹「不合适」原因层
  const [待标记, 设待标记] = useState<推荐候选 | null>(null);
  // 本次进屏内点过「让AI代理去聊」的人：卡先留在原位显示「AI代理已接触」，
  // 让用户看到反馈；离开这一屏再回来就不再出现（他已经在「在谈」里了）
  const 本次已接触 = useRef<Set<string>>(new Set());

  const { 当前岗位编号, 不合适候选, 收藏候选, 已接触推荐 } = 状态;

  const 过滤后 = useMemo(() => {
    return 状态.推荐列表.filter((人) => {
      // ① 推荐流必须随顶栏岗位走：切岗位换的是「这个岗位的候选池」，不是同一批人换个标题
      if (人.岗位编号 !== 当前岗位编号) return false;
      // ② 已标记「不合适」的不再出现（可在「已筛掉的候选」里撤销）
      if (不合适候选[人.编号]) return false;
      // ②b 已让代理去聊的：人已经进「在谈」，推荐流里不再重复出现（标注 11:52）。
      //     本次会话里刚点的那张卡先留着显示「AI代理已接触」，下次进来才消失
      if (已接触推荐.includes(人.编号) && !本次已接触.current.has(人.编号)) return false;
      // 到这里就没有本地档位过滤了：按规则筛人是代理的活（筛选抽屉已于 2026-09-09 删除）
      return true;
    });
  }, [状态.推荐列表, 当前岗位编号, 不合适候选, 已接触推荐]);

  // 本岗位一共有多少推荐（不含已标不合适的）—— 空态文案要靠它区分「本来就没有」和「都处理过了」
  const 本岗总数 = 状态.推荐列表.filter(
    (人) => 人.岗位编号 === 当前岗位编号 && !不合适候选[人.编号]
  ).length;

  // 顶栏原本带「筛选 · N ▾」角标（N = 生效企业规则数），2026-09-09 产品负责人定稿删筛选后
  // 顶栏不再读规则数；规则清单只在 企业代理设置 页维护。
  // 「薪资带有交集」结论及其岗位薪资带取值链已整体删除（2026-09-08 产品负责人定稿）：
  // 推荐卡不再接 岗位薪资带 prop。

  return (
    <主页外壳>
      <企业顶栏 />

      {/* 问AI代理横幅：与「在谈」子视图同款同位（标注 2026-08-19 18:03）*/}
      <代理横幅
        前文="按这个岗位的硬性条件筛出"
        强调={`${本岗总数} 个推荐候选`}
        按下={() => 跳转(路径.企业问AI代理)}
      />

      {/* 横幅与列表之间的固定留白（镜像看市场横幅下方的占位） */}
      <div style={{ height: 10, flex: 'none' }} />

      <下拉刷新>
      <滚动区>
        <div className={样式.列表}>
          {过滤后.length === 0 ? (
            <div className={样式.空态}>
              {本岗总数 === 0
                ? '这个岗位还没有推荐候选，让代理再找一批试试。'
                : '这个岗位的推荐候选都处理过了，让代理再找一批试试。'}
            </div>
          ) : (
            过滤后.map((人) => (
              <div key={人.编号} className={样式.滑动包}>
                <滑动行
                  操作={[{ 文字: '不合适', 按下: () => 设待标记(人) }]}
                  打开={滑开的 === 人.编号}
                  请求打开={(开) => 设滑开的(开 ? 人.编号 : null)}
                >
                  <招聘推荐卡
                    信息={从Mock推荐到卡信息(人)}
                    匹配分={人.匹配分}
                    收藏={收藏候选.includes(人.编号)}
                    收藏禁用={false}
                    滑开={滑开的 === 人.编号}
                    操作状态={状态.已接触推荐.includes(人.编号)
                      ? { kind: '回执', 文案: 'AI代理已接触' }
                      : { kind: '可委托', 提交中: false }}
                    打开={() => 跳转(路径.匿名在线简历(人.编号))}
                    切收藏={() => 派发({ 型: '切收藏候选', 编号: 人.编号 })}
                    委托={() => {
                      // Mock 原型语义：点了就进「在谈」，本次进屏先留卡显示回执
                      本次已接触.current.add(人.编号);
                      派发({ 型: '接触推荐候选', 编号: 人.编号 });
                    }}
                  />
                </滑动行>
              </div>
            ))
          )}

          {/* 补给入口：推荐流是有限的，翻到底要有「再来一批」而不是一堵墙 */}
          <button
            className={`${样式.补给键} 可点`}
            onClick={() => {
              派发({ 型: '补给推荐' });
              // 诚实反馈：再扫一轮只会新增人选，绝不召回你已经否决过的
              // （回归发现原文案「此前标记不合适的候选重新进入推荐流」与
              //  「已筛掉的候选」页的承诺自相矛盾）
              轻提示('代理已再扫一轮，暂时没有新的人选 · 有新的会直接进推荐流');
            }}
          >
            让代理再找一批
          </button>
        </div>
      </滚动区>
      </下拉刷新>

      {待标记 ? (
        <不合适原因层
          代号={待标记.代号}
          关闭={() => 设待标记(null)}
          选定={(原因) => {
            派发({ 型: '标记不合适', 编号: 待标记.编号, 原因 });
            设待标记(null);
            轻提示(`已标记「${原因}」· 可在「已筛掉的候选」里撤销`);
          }}
        />
      ) : null}
    </主页外壳>
  );
}

/** Backend 分支（P4）：列表只吃当前岗位的招聘可用候选快照与 P4 操作。 */
function Backend候选推荐() {
  const { 状态, 数据源模式, 后端状态, 操作 } = use应用状态();
  const { 跳转 } = use导航();
  // 同一时刻只允许一张卡滑开，存的是那张卡的推荐编号
  const [滑开的, 设滑开的] = useState<string | null>(null);
  // 待选原因的卡；非 null 时弹「不合适」原因层
  const [待标记, 设待标记] = useState<P4招聘候选页面 | null>(null);
  // （「只看收藏」本地开关随 候选筛选抽屉 在 2026-09-09 删除：列表不再做收藏过滤）
  // 反馈写进行中（收藏 / 淘汰 / 再找一批）：这几件事共用同一资源与既有互斥，锁保持原样。
  // 委托不再进这把整页锁 —— 它按业务 pair 单独忙（见 委托中）。
  const [反馈中, 设反馈中] = useState(false);
  // Task 5：委托忙态按业务 pair（jobId|recommendationId）隔离 —— 等一张卡的 POST 时，
  // 其他卡照样能浏览、收藏和发起委托；同一张卡连点仍只产生一次请求（操作层另有单飞）。
  const [委托中, 设委托中] = useState<ReadonlySet<string>>(() => new Set());
  // Task 6 合同阻断：组织对账后权威岗位仍 ready 的「数据状态异常」——屏幕局部、按 job
  // 隔离的持久状态；切岗即清、重挂天然复位，绝不外存到全局（§7.7）。
  const [数据异常岗位, 设数据异常岗位] = useState<string | null>(null);

  const 是后端 = 数据源模式 === 'backend';
  // Backend 水合后 当前岗位编号 与 岗位列表[].编号 都是 BFF job_id（从BFF岗位 编号=dto.job_id）
  const 当前岗位编号 = 状态.当前岗位编号;
  // 招聘 scope 只能是自己名下「在招」的那个 job_id：选新当前岗 在一个在招岗都没有时会
  // 保留上一个（可能已归档）的编号，拿它当 scope 就是拿归档岗去要推荐。
  // 与候选侧「服务端 active 意向才进市场流」同一条规则：核不实就不发任何 P4 请求（宁空勿错）。
  const 活跃岗位 = 是后端 && 当前岗位编号 !== '' &&
      状态.岗位列表.find((岗) => 岗.编号 === 当前岗位编号)?.状态 === '在招'
    ? 当前岗位编号
    : null;

  // 组织前提（与候选侧「服务端 active 意向才进市场流」同一口径）：只认后端权威 owner 投影
  // （后端状态.岗位快照[job_id]）的 verified + hiring_organization_ref，绝不拿公司名/声明当真。
  // unknown = 当前岗还没水合出 owner 投影（可能只是还没回来），blocked = 权威事实说明受阻。
  const ownerJob = 活跃岗位 === null ? null : 后端状态.岗位快照?.[活跃岗位];
  const 组织前提 = 活跃岗位 === null
    ? ({ kind: 'unknown' } as const)
    : 判断P4招聘组织前提(ownerJob);
  // 组织前提没就绪就一个 P4 请求都不发：注册/加载/重读/刷新/轮询全部由这个值闸住
  const 就绪岗位 = 组织前提.kind === 'ready' ? 活跃岗位 : null;

  // 刷新请求的报错要按「发起那一刻的岗位 + 现在的权威前提」判定，不能拿渲染闭包里的旧值，
  // 也不能拿别的岗位的受阻事实去翻译这次的错 —— 两个 ref 永远指向本次渲染的权威值。
  const 当前岗位引用 = useRef(活跃岗位);
  const 组织前提引用 = useRef(组织前提);
  当前岗位引用.current = 活跃岗位;
  组织前提引用.current = 组织前提;

  const 当前数据异常 = 数据异常岗位 === 活跃岗位;
  // 切岗即清：合同块绝不跟着岗位走，回到同一岗位也不带旧阻断（重挂由组件生命周期复位）
  useEffect(() => {
    设数据异常岗位(null);
  }, [活跃岗位]);

  // Task 5：本次进屏发起过委托的业务 pair（jobId|recommendationId）。
  // 周期 = 主体 + 角色 + scope + 本次挂载：离屏、切岗（含 A→B→A）、换主体都结束旧周期
  // 并清空集合 —— 切回旧 scope 是新周期，不恢复它的暂留。刷新后自然为空，
  // 由权威推荐摘要恢复成功过滤。
  const 本次委托 = useRef<Set<string>>(new Set());
  const 周期引用 = useRef(0);
  const 当前招聘主体 = 后端状态.主体?.last_used_role === 'recruiter'
    ? 后端状态.主体.subject_id
    : null;
  useEffect(() => {
    周期引用.current += 1;
    本次委托.current = new Set();
    设委托中(new Set());
    return () => {
      周期引用.current += 1;
      本次委托.current = new Set();
    };
  }, [活跃岗位, 当前招聘主体]);

  // 只选当前岗位自己的快照：键按岗位隔离，切换时旧 scope 的数据天然进不来
  const 后端快照 = 活跃岗位 !== null ? 后端状态.招聘可用候选?.[活跃岗位] : undefined;
  const 后端卡们 = useMemo(
    () => (后端快照 ? 后端快照.items.map((卡) => {
      // 委托状态槽只认 映射P4委托展示 的闭合六态投影：摘要 + 权威回执（按 delegation_id 对上）
      const 委托回执 = 卡.delegation === null
        ? null
        : 后端状态.P4委托回执?.[卡.delegation.delegation_id] ?? null;
      return { 视图: 从P4招聘候选(卡), 卡, 展示: 映射P4委托展示(卡.delegation, 委托回执) };
    }) : []),
    [后端快照, 后端状态.P4委托回执]
  );

  // 进屏 / 切岗位：先注册可见范围再懒加载（操作层的栅栏要靠注册的可见范围对上）；
  // 离开本屏或换 scope 时把可见范围清成 null，别让详情页等屏背上旧范围。
  // 组织前提没就绪时一帧都不注册、一发都不加载 —— 凭空发 P4 请求就是拿没认证的组织当真。
  useEffect(() => {
    if (!是后端 || 就绪岗位 === null) return;
    操作.设置发现推荐范围('recruiter', P4范围键.招聘列表(就绪岗位));
    void 操作.加载招聘候选(就绪岗位).catch(() => undefined);
    return () => 操作.设置发现推荐范围('recruiter', null);
  }, [是后端, 就绪岗位, 操作]);

  // 进行中委托（accepted/evaluating，即 映射P4委托展示.inProgress === true 的那两个状态）
  // 交给页面域轮询钩子；暂停表里的委托把状态文案覆盖成中性「进度未知」—— 绝不伪造终态回执。
  // Mock 不开节拍。
  const 进行中委托 = useMemo(
    () => 后端卡们.flatMap(({ 卡, 展示 }) =>
      展示?.inProgress === true && 卡.delegation !== null
        ? [{
          role: 'recruiter' as const,
          delegationId: 卡.delegation.delegation_id,
          // inProgress === true 已闭合出 accepted/evaluating 两员
          state: 展示.state === 'accepted' ? ('accepted' as const) : ('evaluating' as const),
        }]
        : []),
    [后端卡们]
  );
  // terminal summary 单次权威补读：摘要已 refused/failed 而权威回执表缺这条 ID 时，
  // 钩子立即补读一次拿回拒绝/失败码 —— 页面摘要永远不给原因，回执来了才解释
  const 待恢复终态 = useMemo(
    () => 后端卡们.flatMap(({ 卡 }) => {
      const summary = 卡.delegation;
      if (summary === null || summary.delegation_id === '') return [];
      if (summary.state !== 'refused' && summary.state !== 'failed') return [];
      if (后端状态.P4委托回执?.[summary.delegation_id] !== undefined) return [];
      return [{
        role: 'recruiter' as const,
        delegationId: summary.delegation_id,
        state: summary.state,
      }];
    }),
    [后端卡们, 后端状态.P4委托回执]
  );
  const 进度未知 = use发现推荐委托轮询({
    开启: 是后端 && 就绪岗位 !== null,
    委托: 进行中委托,
    待恢复终态,
    刷新: 操作.刷新委托,
    // scope 变化即结束本轮询周期：换岗位不带走上一岗位的连续失败计数（§8.3）
    范围键: 活跃岗位,
  });

  // 下拉只重读当前 scope（GET）；「让代理再找一批」才建新批次（POST+GET）。
  // 下拉把这个 Promise 交回 下拉刷新：转圈等真实 GET settle，不是干等 900ms。
  const 重读当前范围 = () => {
    if (就绪岗位 === null) return;
    // 加载失败（含下拉重读）的文案由操作层落进快照 error，列表上方的错误行负责呈现
    return 操作.加载招聘候选(就绪岗位, true).catch(() => undefined);
  };
  // 「让代理再找一批」POST 建新批次。POST 以精确组织 409 失败时操作层已做一次 Owner Jobs
  // 权威重读：组织受阻事实由水合后的岗位快照驱动既有受阻态（这里不 toast）；权威岗位
  // 仍 ready 的合同漂移落本地持久「数据状态异常」块并禁用本岗刷新；其余错误一律 P4 闭合
  // 文案，绝不制造组织 UI。旧 recommendation_unavailable 不再解释为组织认证错误。
  const 请代理再找一批 = () => {
    if (活跃岗位 === null || 组织前提.kind !== 'ready' || 当前数据异常) return;
    const 发起岗位 = 活跃岗位;
    void 操作.刷新招聘候选(发起岗位).catch((错误: unknown) => {
      if (错误 instanceof BFF错误
        && 错误.status === 409
        && 错误.code === 'organization_verification_required') {
        return; // 权威水合已驱动受阻态，组织指引不再由 toast 冒充
      }
      if (错误 instanceof BFF错误
        && 错误.code === 'invalid_response'
        && 当前岗位引用.current === 发起岗位
        && 组织前提引用.current.kind === 'ready') {
        设数据异常岗位(发起岗位); // 持久 inline 合同块，按 job 隔离
        return;
      }
      轻提示(P4错误文案(错误));
    });
  };

  // 收藏：服务端先行，成功后权威快照回改每一处出现；失败卡片原地不动
  const 切收藏 = async (视图: P4招聘候选页面) => {
    if (反馈中 || 活跃岗位 === null) return;
    设反馈中(true);
    try {
      await 操作.设置候选收藏(活跃岗位, 视图.recommendationId, !视图.收藏);
    } catch (错误) {
      轻提示(P4错误文案(错误));
    } finally {
      设反馈中(false);
    }
  };

  // 委托：无确认层（招聘侧没有披露确认动作），点了就发起；终态/拒绝回执由操作层
  // 抛成带文案的错误，catch 呈现即可。成功不跳页 —— 卡上的委托摘要自己长出状态标。
  // 忙态只锁这一对 pair；本次周期集合先记再发，随后的权威成功才据此暂留。
  const 委托候选 = async (视图: P4招聘候选页面) => {
    if (活跃岗位 === null) return;
    const 键 = 委托键(活跃岗位, 视图.recommendationId);
    if (委托中.has(键)) return;
    // 记录只表示「这一下是我点的」，不授权成功；显示成功仍要过权威成功谓词
    本次委托.current.add(键);
    设委托中((旧) => new Set(旧).add(键));
    const 起始周期 = 周期引用.current;
    try {
      await 操作.委托招聘候选(活跃岗位, 视图.recommendationId);
    } catch (错误) {
      // 迟到栅栏：换岗/主体/离屏后的失败不再打扰新周期
      if (周期引用.current === 起始周期) 轻提示(P4错误文案(错误));
    } finally {
      // 换过周期就不动新周期的忙态（旧 finally 绝不给新请求解锁）
      if (周期引用.current === 起始周期) {
        设委托中((旧) => {
          const 新 = new Set(旧);
          新.delete(键);
          return 新;
        });
      }
    }
  };

  // 淘汰：服务端先行，PUT 成功并权威重读后卡片才从可用流消失；失败原地保留。
  // 原因用四员闭合文案反向成 BFF 码，绝不发展示文案上 wire。
  const 标记不合适 = async (视图: P4招聘候选页面, 原因: string) => {
    // 与 切收藏/委托候选 同一把闸：操作层的按资源单飞会丢弃并发写并直接 resolve，
    // 没有这道闸就会给一次根本没发生的淘汰弹成功提示
    if (反馈中 || 活跃岗位 === null) return;
    设待标记(null);
    设反馈中(true);
    try {
      await 操作.淘汰候选(活跃岗位, 视图.recommendationId, P4淘汰原因码(原因));
      轻提示(`已标记「${原因}」· 可在「已筛掉的候选」里撤销`);
    } catch (错误) {
      轻提示(P4错误文案(错误));
    } finally {
      设反馈中(false);
    }
  };

  // Task 5：待选流 = 权威快照减去「进屏前就已开案」的卡（它已经是一张在谈单）；
  // 本次进屏点过、随后被权威投影确认成功的那张先留在原位显示状态标，顺序不变，
  // 下次进来才消失。只是渲染投影：不动 P4 原始缓存、不删详情坐标、不结束任何 Case。
  const 待选卡们 = useMemo(
    () => 后端卡们.filter(({ 视图, 展示 }) => !P4已开案(展示)
      || (活跃岗位 !== null && 本次委托.current.has(委托键(活跃岗位, 视图.recommendationId)))),
    [后端卡们, 活跃岗位]
  );
  // 显示列表 = 待选流本身（原「只看收藏」本地过滤随抽屉删除，2026-09-09 产品负责人定稿）
  const 显示列表 = 待选卡们;

  // Backend 列表态（组织前提就绪时才会渲染到这里）：首载进行中 / 首载失败（给明确重试）；
  // 已有卡的快照不管阶段（刷新失败保留旧卡，错误单独一行交代）都算「有卡」。
  const 后端列表态: '载入中' | '失败' | '有卡' =
    后端快照 === undefined ||
        (后端快照.items.length === 0 &&
          (后端快照.阶段 === '未开始' || 后端快照.阶段 === '进行中'))
      ? '载入中'
      : 后端快照 !== undefined && 后端快照.items.length === 0 && 后端快照.阶段 === '失败'
        ? '失败'
        : '有卡';

  // （顶栏原「筛选 · N ▾」角标的规则数计算随删筛选一起删除，2026-09-09 产品负责人定稿）

  // 前提未知时的中性原因（无在招岗 / owner 投影未水合是两种不同的未知，但都不预判组织状态）
  const 前提未知原因 = 活跃岗位 === null ? '还没有在招的岗位' : '正在加载岗位信息';

  return (
    <主页外壳>
      <企业顶栏 />

      {/* 问AI代理横幅：与「在谈」子视图同款同位（标注 2026-08-19 18:03）。
          组织前提受阻时这个横幅槽换成交代前提 + 去实名认证 —— 列表根本不会来。 */}
      {组织前提.kind === 'blocked' ? (
        <代理横幅
          前文="匿名候选推荐需要已验证的用人组织"
          强调="先完成企业实名认证"
          动作文="去认证 ›"
          按下={() => 跳转(路径.企业实名认证)}
        />
      ) : (
        <代理横幅
          前文="按这个岗位的硬性条件筛出"
          强调={`${后端卡们.length} 个推荐候选`}
          // 交付 G：Backend 的代理页是导航说明而非自由对话，入口文案不许承诺「问AI代理」
          动作文="查看代理功能 ›"
          按下={() => 跳转(路径.企业问AI代理)}
        />
      )}

      {/* 横幅与列表之间的固定留白（镜像看市场横幅下方的占位） */}
      <div style={{ height: 10, flex: 'none' }} />

      <下拉刷新 刷新={是后端 && 就绪岗位 !== null ? 重读当前范围 : undefined}>
      <滚动区>
        <div className={样式.列表}>
          {活跃岗位 === null ? (
            <div className={样式.空态}>
              <div>还没有在招的岗位</div>
              <div>代理只替在招岗位找候选，先去发布或重开一个岗位吧。</div>
            </div>
          ) : 组织前提.kind === 'unknown' ? (
            // owner 投影还没水合：组织前提未知，只能中性加载 —— 不预判、更不发请求
            <div className={样式.空态}>正在加载岗位信息…</div>
          ) : 组织前提.kind === 'blocked' ? (
            // 权威事实说明组织受阻：重复原因 + 两条既有出路，绝不拿公司名当已认证
            <div className={样式.空态}>
              <div>这个岗位还没挂到已验证的用人组织</div>
              <div>先完成企业实名认证，或用邀请加入企业，代理才能替这个岗位找候选。</div>
            </div>
          ) : 后端列表态 === '载入中' ? (
            <div className={样式.空态}>正在加载这个岗位的推荐候选…</div>
          ) : 后端列表态 === '失败' ? (
            <div className={样式.空态}>
              <div>推荐暂时加载不了</div>
              <div>{后端快照?.error}</div>
              <button className={`${样式.空态重试} 可点`} onClick={重读当前范围}>
                重试
              </button>
            </div>
          ) : (
            <>
              {/* 合同阻断（Task 6）优先占错误行：对账后权威岗位仍 ready 的持久「数据状态
                  异常」块；无合同时仍走原快照错误行（刷新未决等）。 */}
              {当前数据异常 ? (
                <div className={样式.错误行}>数据状态异常，请稍后再试</div>
              ) : 后端快照?.error && 后端卡们.length > 0 && !后端快照.刷新中 ? (
                <div className={样式.错误行}>{后端快照.error}</div>
              ) : null}
              {待选卡们.length === 0 ? (
                <div className={样式.空态}>
                  这个岗位还没有推荐候选，让代理再找一批试试。
                </div>
              ) : (
                显示列表.map(({ 视图, 卡, 展示 }) => {
                  // 状态槽只认 映射P4委托展示 的闭合六态：进行中给状态标、开案带服务端 Case
                  // 才给「查看进展」、终态给禁用的权威文案（附上服务端拒绝原因，如有）
                  const 委托进度未知 = 展示?.inProgress === true && 卡.delegation !== null
                    && 进度未知.has(卡.delegation.delegation_id);
                  // 开案成功（case_started + 非空 case_id）用本页 Mock 已有的成功文案，
                  // 不再显示「已创建真实在谈」，也不给 Case 导航（Spec §7.1）
                  const 委托文字 = P4已开案(展示)
                    ? 'AI代理已接触'
                    : 委托进度未知
                      ? P4委托进度未知文案
                      : 展示 === null
                        ? '让AI代理去聊'
                        : `${展示.copy}${展示.reason === null ? '' : `：${展示.reason}`}`;
                  // 只有这张卡自己的委托在飞：别的卡照样能点
                  const 本卡委托中 = 活跃岗位 !== null
                    && 委托中.has(委托键(活跃岗位, 视图.recommendationId));
                  return (
                    <div key={视图.recommendationId} className={样式.滑动包}>
                      <滑动行
                        操作={[{ 文字: '不合适', 禁用: 反馈中, 按下: () => 设待标记(视图) }]}
                        打开={滑开的 === 视图.recommendationId}
                        请求打开={(开) => 设滑开的(开 ? 视图.recommendationId : null)}
                      >
                        <招聘推荐卡
                          信息={从招聘摘要到卡信息(视图.候选摘要 ?? null)}
                          匹配分={视图.匹配分}
                          收藏={视图.收藏}
                          收藏禁用={反馈中}
                          滑开={滑开的 === 视图.recommendationId}
                          // 未委托才给可委托槽；有委托态就只渲染上面的权威文案，卡片不做业务推断
                          操作状态={展示 === null
                            ? { kind: '可委托', 提交中: 本卡委托中 }
                            : { kind: '回执', 文案: 委托文字 }}
                          切收藏={() => void 切收藏(视图)}
                          委托={() => void 委托候选(视图)}
                          // J（Task 8）：Backend 走 canonical 双坐标 —— 岗位取这张卡
                          // 自己的 jobId（与推荐同源），Mock 保留旧路由（原型卡片无 job 概念）
                          打开={() => 跳转(是后端
                            ? 路径.后端匿名在线简历(视图.jobId, 视图.recommendationId)
                            : 路径.匿名在线简历(视图.recommendationId))}
                        />
                      </滑动行>
                    </div>
                  );
                })
              )}
            </>
          )}

          {/* 补给入口：推荐流是有限的，翻到底要有「再来一批」而不是一堵墙。
              组织受阻时这个键不再是刷新请求：换成加入企业的出路，可访问名带上原因；
              前提未知时键在但不挂任何处理器 —— 激活它绝不能发刷新请求。 */}
          {组织前提.kind === 'blocked' ? (
            <button
              className={`${样式.补给键} 可点`}
              aria-label="匿名候选推荐需要已验证的用人组织，先加入企业"
              onClick={() => 跳转(路径.企业邀请加入)}
            >
              加入企业
            </button>
          ) : (
            <button
              className={`${样式.补给键} ${组织前提.kind === 'ready' && !反馈中 && !当前数据异常 ? '可点' : ''}`}
              disabled={组织前提.kind !== 'ready' || 反馈中 || 当前数据异常}
              aria-label={组织前提.kind === 'ready'
                ? undefined
                : `${前提未知原因}，暂时不能让代理再找一批`}
              onClick={组织前提.kind === 'ready' ? 请代理再找一批 : undefined}
            >
              让代理再找一批
            </button>
          )}
        </div>
      </滚动区>
      </下拉刷新>

      {待标记 ? (
        <不合适原因层
          代号={待标记.代号}
          关闭={() => 设待标记(null)}
          选定={(原因) => void 标记不合适(待标记, 原因)}
        />
      ) : null}
    </主页外壳>
  );
}

/** 企业顶栏：在招岗位切换（左右平铺）+ ＋发岗 → 在谈/推荐子视图。
 *  与「企业在谈候选」同款（版式镜像求职端 顶部意向栏），两屏切换时顶部不动。
 *  原子视图行右端的「筛选 ▾」及 筛选数 / 开筛选 两个 props 已删（2026-09-09 产品负责人定稿）。 */
function 企业顶栏() {
  const { 状态, 派发 } = use应用状态();
  const { 跳转 } = use导航();

  // 顶栏只平铺在招中的岗位；已归档的收在 D17 岗位管理里
  const 在招们 = 状态.岗位列表.filter((岗) => 岗.状态 === '在招');

  return (
    <div className={样式.顶栏}>
      <div className={样式.岗位行}>
        {/* 在招岗位放进横向滚动条里，＋ 留在外面固定住 —— 与求职端意向胶囊条同一套类
            （.岗位滚动条 / .岗位选中 / .岗位未选 都 composes 自 顶部意向栏.module.css）。
            原来是把 N 个岗位直接平铺在 .岗位行 上、靠 max-width 截断，8–15 个岗时整个顶栏失效。
            这里也不再挂全局 .单行：横着滚就是为了整名可读，再打省略号等于白滚。 */}
        <div className={样式.岗位滚动条}>
          {在招们.map((岗) => {
            const 选中 = 岗.编号 === 状态.当前岗位编号;
            return (
              <button
                key={岗.编号}
                className={`${选中 ? 样式.岗位选中 : 样式.岗位未选} 可点`}
                onClick={() => 派发({ 型: '切当前岗位', 编号: 岗.编号 })}
              >
                {岗位名截短(岗.名称)}
              </button>
            );
          })}
        </div>
        <span className={样式.岗位行右}>
          <button
            className={`${样式.加号} 可点`}
            onClick={() => 跳转(路径.发布岗位)}
            aria-label="发布新岗位"
          >
            ＋
          </button>
        </span>
      </div>

      <div className={样式.子视图行}>
        {(['在谈', '推荐'] as const).map((视图) => (
          <button
            key={视图}
            className={`${状态.企业子视图 === 视图 ? 样式.子视图选中 : 样式.子视图未选} 可点`}
            onClick={() => 派发({ 型: '企业切子视图', 子视图: 视图 })}
          >
            {视图}
          </button>
        ))}
      </div>
    </div>
  );
}

/** 「不合适」原因层：负反馈必须带原因，否则代理学不到东西，只是把人藏起来 */
function 不合适原因层({
  代号,
  选定,
  关闭,
}: {
  代号: string;
  选定: (原因: string) => void;
  关闭: () => void;
}) {
  return (
    <弹层框架 标签="标记候选不合适" 遮罩类名={样式.遮罩} 面板类名={样式.原因层} 关闭={关闭}>
        <div className={样式.抓手} />
        <div className={样式.原因标题}>{代号} 哪里不合适？</div>
        <div className={样式.原因说明}>
          代理会按这条反馈调整后续寻访，也可以随时在「已筛掉的候选」里撤销。
        </div>
        {不合适原因表.map((原因) => (
          <button key={原因} className={`${样式.原因项} 可点`} onClick={() => 选定(原因)}>
            {原因}
            <span className={样式.原因尖括号}>›</span>
          </button>
        ))}
        <button className={`${样式.原因取消} 可点`} onClick={关闭}>
          取消
        </button>
    </弹层框架>
  );
}
